entries[49487] = { ["name"] = "Geläuterter Talisman mit Onyxiablut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Purified Onyxia Blood Talisman] (1)\nSchmuck\nStellt alle 5 Sek. + 101 Gesundheit wieder her.\n+15 Feuerwiderstand\nAnlegen: Erhöht die Verteidigungswertung um 69.\nAnlegen: Erhöht Eure Parierwertung um 108." }
entries[49488] = { ["name"] = "Glänzender Splitter der Schuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 80\nAnlegen: Stellt alle 5 Sek. 96 Mana wieder her.\n\nGlänzende Scherbe der Götter (0/2)\nGlänzender Splitter der Schuppe\nGlänzender Splitter der Flamme\n(2) Set : Erhöht die Zaubermacht um 250.\n(2) Set : Eure direkten Heilzauber haben eine Chance, den Effekt 'Kauterisierende Heilung' hervorzurufen. Eure direkten Schadenszauber haben eine Chance, den Effekt 'Sengende Flammen' zu verursachen. (Procchance: 25%, 50s Abklingzeit)" }
