entries[49496] = { ["name"] = "Verstärkter Schattenschlag", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n634 - 951 Schaden Tempo 3.10\n(255.65 Schaden pro Sekunde)\n+120 Beweglichkeit\n+126 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nErhöht die Angriffskraft um 2812 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die kritische Trefferwertung um 73.\nAnlegen: Erhöht die Angriffskraft um 157.\nAnlegen: Erhöht den Rüstungsdurchschlag um 89.\nTrefferchance: Stiehlt dem feindlichen Ziel 100 to 180 Leben.\nBenutzen: Beschwört einen neuen verstärkten Donnerschlag.\n1 Aufladung" }
entries[49497] = { ["name"] = "Verstärkter Donnerschlag", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n634 - 951 Schaden Tempo 3.10\n(255.65 Schaden pro Sekunde)\n+89 Beweglichkeit\n+180 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nErhöht die Angriffskraft um 2812 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die Tempowertung um 63.\nAnlegen: Erhöht die Angriffskraft um 190.\nAnlegen: Erhöht Eure Waffenkundewertung um 71.\nTrefferchance: Überzieht bis zu 3 Ziele mit 150 to 250 Naturschaden. Der angerichtete Schaden verringert sich jedoch von Ziel zu Ziel." }
